/**
 * generated by stackra gen from the routes' `path` (src/routes/<name>/<name>.route.ts),
 * stackra.config.ts (scheme), src/config/identity.config.ts (nativeRedirectPath) and
 * src/config/env.config.ts (appOrigin) — do not edit
 * Purpose: the deep-link map for the custom scheme and the universal-link origin. Static paths are
 *          sorted before parameterised ones (`/orders/new` before `/orders/:orderId`). The identity
 *          callback is filtered out so navigation never sees an authorization code.
 * Boundary: React Navigation's linking config takes each route's absolute path without its leading
 *           slash; the route declarations keep the slash.
 * Runtime: react-native
 */
import type { LinkingOptions } from "@react-navigation/native";
import * as Linking from "expo-linking";
import { env } from "#stackra/env";
import type { RouteParams } from "#stackra/routes";

export const linking: LinkingOptions<RouteParams & { tabs: undefined }> = {
  prefixes: [Linking.createURL("/", { scheme: "acme" }), `${env.appOrigin}/m`],
  filter: (url) => !url.includes("auth/callback"),
  config: {
    screens: {
      tabs: {
        screens: {
          "tab:home": { screens: { home: "" } },
          "tab:orders": { screens: { orders: "orders" } },
          "tab:settings": { screens: { settings: "settings" } },
        },
      },
      create_order: "orders/new",
      order_detail: "orders/:orderId",
      scan: "scan",
      announcements: "announcements",
      inbox: "inbox",
      notification_preferences: "settings/notifications",
      profile: "profile",
    },
  },
};
